-- Generated by scripts/remediation/hero_repair/apply.py - do not edit by hand.
-- 5438 row(s) over 2719 site(s); scope source_id = 'ancient_nerds'.
-- Every UPDATE is conditioned on the old value; every change is journalled in the same
-- transaction, so the audit trail cannot disagree with the data.
\set ON_ERROR_STOP on
BEGIN;

CREATE TEMP TABLE _hero_plan (
    image_id    BIGINT PRIMARY KEY,
    site_id     UUID NOT NULL,
    old_value   BOOLEAN NOT NULL,
    new_value   BOOLEAN NOT NULL,
    change_key  TEXT NOT NULL,
    reason      TEXT NOT NULL,
    evidence    JSONB NOT NULL
) ON COMMIT DROP;


DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER;
    r        RECORD;
BEGIN
    SELECT count(*) INTO expected FROM _hero_plan;

    -- scope guard 1: every planned site is a curated site
    SELECT count(*) INTO bad
      FROM _hero_plan p LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        RAISE EXCEPTION 'hero repair: % planned site(s) are not ancient_nerds', bad;
    END IF;

    -- scope guard 2: every planned image lives on the site the plan names
    SELECT count(*) INTO bad
      FROM _hero_plan p JOIN wiki_images w ON w.id = p.image_id
     WHERE w.site_id IS DISTINCT FROM p.site_id;
    IF bad > 0 THEN
        RAISE EXCEPTION 'hero repair: % planned image(s) do not belong to their site', bad;
    END IF;

    -- scope guard 3: the plan is internally consistent - one promotion and one
    -- demotion per touched site, and no row twice
    SELECT count(*) INTO bad FROM (
        SELECT p.site_id FROM _hero_plan p GROUP BY p.site_id
         HAVING count(*) FILTER (WHERE p.new_value) <> 1
             OR count(*) FILTER (WHERE NOT p.new_value) <> 1) x;
    IF bad > 0 THEN
        RAISE EXCEPTION 'hero repair: % site(s) without exactly one promotion and one demotion', bad;
    END IF;

    -- every row through the journal function, so the UPDATE and its journal row
    -- commit together or neither does; it raises if the old value does not match
    FOR r IN SELECT * FROM _hero_plan ORDER BY site_id, new_value, image_id LOOP
        moved := moved + apply_remediation_change(
            'wiki_images', 'is_hero', 'id', r.image_id::text, 
            r.old_value::text, r.new_value::text,
            'T09/hero-not-best', '2026-09-20_remediation-rollback', r.change_key, 'authoritative', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'hero repair: % row(s) changed, % planned', moved, expected;
    END IF;

    -- the invariant the repair must leave behind: one hero per touched site
    -- (DISTINCT: _hero_plan holds two rows per site, and a plain join would count each
    --  hero row twice - the check would then fail on a correct repair)
    SELECT count(*) INTO bad FROM (
        SELECT s.site_id FROM (SELECT DISTINCT site_id FROM _hero_plan) s
          JOIN wiki_images w ON w.site_id = s.site_id
         GROUP BY s.site_id HAVING count(*) FILTER (WHERE w.is_hero) <> 1) x;
    IF bad > 0 THEN
        RAISE EXCEPTION 'hero repair: % touched site(s) do not end with exactly one hero', bad;
    END IF;

    RAISE NOTICE 'hero repair: % row(s) changed and journalled over % site(s)',
        moved, (SELECT count(DISTINCT site_id) FROM _hero_plan);
END $$;

COMMIT;

-- Post-commit read: the numbers the report quotes, from the database, not from the plan.
SELECT 'journal rows for this run stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = '2026-09-20_remediation-rollback'
UNION ALL
SELECT 'curated hero rows', count(*)::text
  FROM wiki_images w JOIN unified_sites u ON u.id = w.site_id
 WHERE u.source_id = 'ancient_nerds' AND w.is_hero
UNION ALL
SELECT 'curated sites with more than one hero', count(*)::text FROM (
    SELECT u.id FROM unified_sites u JOIN wiki_images w ON w.site_id = u.id
   WHERE u.source_id = 'ancient_nerds' GROUP BY u.id
  HAVING count(*) FILTER (WHERE w.is_hero) > 1) x;
